def fill_defaults(apps, schema_editor):
    """Give existing repositories the default request-a-copy emails, as new
    ones get them from repository_settings.json when created."""
    path = os.path.join(settings.BASE_DIR, "utils/install/repository_settings.json")
    with codecs.open(path, "r", encoding="utf-8") as handle:
        defaults = json.load(handle)[0]
    Repository = apps.get_model("repository", "Repository")
    for repository in Repository.objects.all():
        changed = [name for name in FIELDS if not getattr(repository, name)]
        for name in changed:
            setattr(repository, name, defaults[name])
        if changed:
            repository.save(update_fields=changed)


